import os
import threading
from contextlib import contextmanager
from inspect import stack
from logging import Logger
from os.path import basename

from taf.sbts.oam.coam.admin import admin as taf_admin

from ta_logcollector.logger import get_net_logger
from ta_logcollector.settings import BIP_THREAD_NAME, DEF_ALL_PLUGS_STOP_TIMEOUT, SERVER_HOST

logger = Logger("LC")
SNAPSHOT_ALIAS = "snapshot_{}".format(SERVER_HOST)


def _collect_admin_snapshot(log_file):
    # type: (str) -> None
    """
    Use Admin to collect tech snapshot file from enb.
    :param log_file: string containing the destination where to save snapshot file and its name
    """
    admin = taf_admin()
    try:
        admin.setup_admin(alias=SNAPSHOT_ALIAS)
        admin.collect_snapshot(target_file_name=log_file, timeout=600, alias=SNAPSHOT_ALIAS)
    except Exception as exc:
        logger.error(
            "Could not collect snapshot file. Exception [{}] caught [{}]]".format(type(exc).__name__, exc),
            exc_info=True,
        )
    finally:
        admin.teardown_admin(alias=SNAPSHOT_ALIAS)


def _wait_for_gnb_bip_collection_to_finish():
    for thread in filter(lambda t: t.name == BIP_THREAD_NAME, threading.enumerate()):
        if thread.name == BIP_THREAD_NAME:
            logger.info("Snapshot plugin waiting for gNB BIP collection finished")
            thread.join(timeout=DEF_ALL_PLUGS_STOP_TIMEOUT)
            logger.info("gNB BIP collection finished")
            break


def start():
    """Method does nothing, this plugin does not require activation."""
    logger.info("Inside {} start".format(basename(__file__)))


def stop(log_dir):
    # type: (str) -> None
    """
    Method should collect and store snapshot file from enb
    :param log_dir: string containing the destination where to save snapshot file
    """
    _wait_for_gnb_bip_collection_to_finish()
    logger.info("Inside {} before stop".format(basename(__file__)))
    log_file = os.path.join(log_dir, "snapshot_{}.zip".format(SERVER_HOST))
    _collect_admin_snapshot(log_file)
    logger.info("Inside {} after stop".format(basename(__file__)))


@contextmanager
def snapshot(log_host, log_port, **kwargs):
    # type: (str, int, Dict[str, str]) ->  Iterator[None]
    """
    Plugin for collecting tech snapshot file from enb. When it starts it does nothing but waits
    for stop action. Then it downloads file from enb and saves it at the destination
    provided by the user.
    :param log_host: IP address of logger host
    :param log_port: port of logger host
    """
    global logger
    logger = get_net_logger(log_host, log_port, "{}_{}".format(stack(0)[0][3], SERVER_HOST))
    log_dir = kwargs.pop("log_dir")
    try:
        start()
        yield
    finally:
        stop(log_dir)
